//! Recurring detection — find the standing charges nobody is looking at.
//!
//! The highest-value capability in the finance set, and the reason is unglamorous: a forgotten
//! subscription is found by NOBODY until something looks for it. It does not appear on a budget, it
//! does not feel like a decision, and it renews on a schedule designed to be unremarkable.
//!
//! The output that matters is the ANNUALISED cost. "$14.99" prompts nothing; "$179.88 a year" prompts
//! a cancellation. Same charge, and only one of those gets acted on.
//!
//! # Confidence, not a verdict
//!
//! A monthly bill whose amount moves — a utility, anything usage-based — is still recurring, and a
//! detector demanding an identical amount would miss exactly the charges worth finding. So regularity
//! and amount stability are scored separately and both are reported. Nothing here decides for the
//! reader; it hands them two numbers and the annual figure.
use crate::money::{money, scale, sum, Currency, Money, Rounding};
use crate::txn::{days_between, merchant_key_default, Txn};

/// How often something recurs. `Irregular` is a real answer, not a failure to classify.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Cadence {
    Weekly,
    Biweekly,
    Monthly,
    Quarterly,
    Annual,
    Irregular,
}

impl Cadence {
    /// How many times a year this lands. `Irregular` has no answer and says so rather than guessing.
    pub fn per_year(self) -> Option<i64> {
        match self {
            Cadence::Weekly => Some(52),
            Cadence::Biweekly => Some(26),
            Cadence::Monthly => Some(12),
            Cadence::Quarterly => Some(4),
            Cadence::Annual => Some(1),
            Cadence::Irregular => None,
        }
    }

    pub fn label(self) -> &'static str {
        match self {
            Cadence::Weekly => "weekly",
            Cadence::Biweekly => "biweekly",
            Cadence::Monthly => "monthly",
            Cadence::Quarterly => "quarterly",
            Cadence::Annual => "annual",
            Cadence::Irregular => "irregular",
        }
    }
}

/// The interval in days each cadence implies, and how far a gap may stray and still count.
const CADENCE_DAYS: [(Cadence, i64, i64); 5] = [
    (Cadence::Weekly, 7, 2),
    (Cadence::Biweekly, 14, 3),
    (Cadence::Monthly, 30, 5),
    (Cadence::Quarterly, 91, 12),
    (Cadence::Annual, 365, 35),
];

#[derive(Debug, Clone, PartialEq)]
pub struct Recurring {
    /// The merchant key the occurrences share — stable across the noise statements add.
    pub key: String,
    /// The most recent description, so a human recognises what it is.
    pub label: String,
    pub account: String,
    pub cadence: Cadence,
    /// Typical amount — the MEDIAN, not the mean: one annual true-up must not move the figure.
    pub typical: Money,
    /// What it costs over a year at this cadence. The number that prompts action.
    pub annualised: Money,
    pub occurrences: usize,
    pub first_seen: String,
    pub last_seen: String,
    /// 0-1, to two decimals. How evenly spaced the occurrences are; 1 is metronomic.
    pub regularity: f64,
    /// 0-1, to two decimals. How stable the amount is; 1 is identical every time.
    pub amount_stability: f64,
    /// Nothing charged for noticeably longer than the cadence predicts. Either it was cancelled or
    /// it is about to hit, and those want different responses — so it is surfaced, not filtered.
    pub lapsed: bool,
}

pub struct DetectOptions<'a> {
    /// Fewest occurrences before something counts as recurring. TWO is deliberate — an annual charge
    /// cannot show three inside a year of statements, and demanding three would hide precisely the
    /// once-a-year renewals that are easiest to forget and most expensive to keep.
    pub min_occurrences: usize,
    /// Ignore inbound money; income has its own capability and its own questions.
    pub outflows_only: bool,
    /// `YYYY-MM-DD` — what "now" is, for the lapsed check. Passed IN, never read from a clock, so
    /// the same data gives the same answer on a re-run and a test is not a moving target.
    pub as_of: &'a str,
}

impl<'a> DetectOptions<'a> {
    /// The defaults the TypeScript kit applies when the caller supplies only `asOf`.
    pub fn new(as_of: &'a str) -> Self {
        DetectOptions { min_occurrences: 2, outflows_only: true, as_of }
    }
}

/// The median, matching the TypeScript exactly — including that an even count ROUNDS THE MIDPOINT.
///
/// `Math.round` is half-up toward positive infinity. Every caller here passes non-negative values
/// (absolute amounts, and day gaps), where half-up and half-away-from-zero agree, so the difference
/// cannot surface — but it is written the way it is so that stays true if a negative ever arrives.
fn median(xs: &[i64]) -> i64 {
    if xs.is_empty() {
        return 0;
    }
    let mut s = xs.to_vec();
    s.sort_unstable();
    let m = s.len() / 2;
    if s.len() % 2 == 1 {
        s[m]
    } else {
        let total = s[m - 1] + s[m];
        // half-up toward +inf: -3/2 is -1.5, which rounds to -1, not -2.
        if total >= 0 { (total + 1).div_euclid(2) } else { -((-total).div_euclid(2)) }
    }
}

fn round2(x: f64) -> f64 {
    (x * 100.0).round() / 100.0
}

/// The cadence whose expected interval the observed gaps sit closest to.
///
/// Regularity measures how tightly the gaps CLUSTER on the expected interval, not merely that the
/// median landed near it: twelve charges at 30 days and twelve alternating 5/55 share a median, and
/// only one of them is a subscription. The alternating case scores 0 and is still reported — the
/// score is the finding, not a filter.
pub fn classify(gaps: &[i64]) -> (Cadence, f64) {
    if gaps.is_empty() {
        return (Cadence::Irregular, 0.0);
    }
    let typical = median(gaps);
    let Some(&(cadence, days, _)) = CADENCE_DAYS.iter().find(|(_, days, tol)| (typical - days).abs() <= *tol) else {
        return (Cadence::Irregular, 0.0);
    };
    let drift = gaps.iter().map(|g| (g - days).abs() as f64).sum::<f64>() / gaps.len() as f64;
    (cadence, (1.0 - drift / days as f64).max(0.0))
}

/// Group by merchant AND account, then judge each group's rhythm.
///
/// The group identity is a `(account, key)` PAIR rather than a joined string. The TypeScript joins
/// them with a NUL byte precisely because a merchant key contains spaces — "rent landlord" — and any
/// printable separator would be ambiguous. A tuple has no separator to get wrong, so the hazard the
/// NUL exists to dodge does not reach this port at all.
///
/// Keyed on the ACCOUNT too: one subscription billed to two cards is two standing charges, and
/// merging them would halve the count while doubling the apparent amount.
pub fn detect_recurring(txns: &[Txn], opts: &DetectOptions) -> Vec<Recurring> {
    // Insertion-ordered, because the output sort is STABLE and ties therefore fall back to the order
    // groups were first seen. A HashMap would make two equal-cost accounts swap between runs.
    let mut groups: Vec<((String, String), Vec<&Txn>)> = Vec::new();
    for t in txns {
        if opts.outflows_only && t.amount.minor >= 0 {
            continue;
        }
        let key = merchant_key_default(&t.description);
        if key.is_empty() {
            continue;
        }
        let id = (t.account.clone(), key);
        match groups.iter_mut().find(|(gid, _)| *gid == id) {
            Some((_, bucket)) => bucket.push(t),
            None => groups.push((id, vec![t])),
        }
    }

    let mut out: Vec<Recurring> = Vec::new();
    for (id, rows) in groups {
        if rows.len() < opts.min_occurrences {
            continue;
        }
        let mut sorted = rows;
        sorted.sort_by(|a, b| a.date.cmp(&b.date));
        let gaps: Vec<i64> = sorted.windows(2).map(|w| days_between(&w[0].date, &w[1].date)).collect();
        let (cadence, regularity) = classify(&gaps);
        if cadence == Cadence::Irregular {
            continue;
        }

        let amounts: Vec<i64> = sorted.iter().map(|t| t.amount.minor.abs()).collect();
        let typical_minor = median(&amounts);
        let spread = amounts.iter().map(|v| (v - typical_minor).abs() as f64).sum::<f64>() / amounts.len() as f64;
        // A group whose typical amount is zero is stable by definition — there is nothing to vary.
        let amount_stability = if typical_minor == 0 { 1.0 } else { (1.0 - spread / typical_minor as f64).max(0.0) };

        let last = sorted[sorted.len() - 1];
        let typical = money(typical_minor, last.amount.currency);
        let (_, expected, tol) = CADENCE_DAYS.iter().find(|(c, _, _)| *c == cadence).copied().expect("a classified cadence is in the table");
        let per_year = cadence.per_year().expect("a classified cadence is never irregular");

        out.push(Recurring {
            key: id.1,
            label: last.description.clone(),
            account: last.account.clone(),
            cadence,
            typical,
            annualised: scale(typical, per_year as f64, Rounding::HalfUp),
            occurrences: sorted.len(),
            first_seen: sorted[0].date.clone(),
            last_seen: last.date.clone(),
            regularity: round2(regularity),
            amount_stability: round2(amount_stability),
            lapsed: days_between(&last.date, opts.as_of) > expected + tol,
        });
    }
    // Biggest annual cost first — the order a reader wants, because it is the order to act in.
    out.sort_by_key(|r| std::cmp::Reverse(r.annualised.minor));
    out
}

/// What every LIVE recurring charge costs in a year, together. Usually the number that lands.
///
/// Lapsed charges are excluded because the figure is meant to be actionable: adding back a
/// subscription that already stopped would overstate what cancelling everything could recover.
pub fn total_annualised(rs: &[Recurring], currency: Currency) -> Result<Money, crate::money::CurrencyMismatch> {
    let live: Vec<Money> = rs.iter().filter(|r| !r.lapsed).map(|r| r.annualised).collect();
    sum(&live, currency)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::{usd, Minor};

    // SYNTHETIC FIXTURES ONLY — no real merchant, amount or account reaches this repo.
    fn t(date: &str, description: &str, minor: Minor, account: &str) -> Txn {
        Txn {
            account: account.to_string(),
            date: date.to_string(),
            description: description.to_string(),
            amount: usd(minor),
        }
    }

    /// Every row here was taken by TRANSPILING AND RUNNING `finance-recurring.ts`, never by reading
    /// it. Four silent divergences in the money port were found exactly this way, and reading the
    /// source would have reproduced each of them faithfully.
    struct Case {
        name: &'static str,
        rows: Vec<Txn>,
        as_of: &'static str,
        outflows_only: bool,
        expect: Vec<Row>,
    }

    /// One expected finding. A named struct rather than a nine-wide tuple, so a mismatched column
    /// is a compile error naming the field instead of a silent shift down the row.
    struct Row {
        key: &'static str,
        account: &'static str,
        cadence: Cadence,
        typical: i64,
        annualised: i64,
        occurrences: usize,
        regularity: f64,
        stability: f64,
        lapsed: bool,
    }

    #[allow(clippy::too_many_arguments)]
    fn row(key: &'static str, account: &'static str, cadence: Cadence, typical: i64, annualised: i64, occurrences: usize, regularity: f64, stability: f64, lapsed: bool) -> Row {
        Row { key, account, cadence, typical, annualised, occurrences, regularity, stability, lapsed }
    }

    fn cases() -> Vec<Case> {
        vec![
            Case {
                name: "alternating 5/55 shares a median with a steady week and must NOT score as one",
                rows: vec![t("2026-01-01", "GYM", -5_000, "a"), t("2026-01-06", "GYM", -5_000, "a"), t("2026-03-02", "GYM", -5_000, "a"), t("2026-03-07", "GYM", -5_000, "a")],
                as_of: "2026-03-20",
                outflows_only: true,
                expect: vec![row("gym", "a", Cadence::Weekly, 5_000, 260_000, 4, 0.0, 1.0, true)],
            },
            Case {
                name: "a steady 30 days is metronomic",
                rows: vec![t("2026-01-01", "GYM", -5_000, "a"), t("2026-01-31", "GYM", -5_000, "a"), t("2026-03-02", "GYM", -5_000, "a")],
                as_of: "2026-03-20",
                outflows_only: true,
                expect: vec![row("gym", "a", Cadence::Monthly, 5_000, 60_000, 3, 1.0, 1.0, false)],
            },
            Case {
                name: "a utility recurs while its amount moves — the whole reason stability is separate",
                rows: vec![t("2026-01-10", "CITY POWER", -8_000, "a"), t("2026-02-10", "CITY POWER", -12_000, "a"), t("2026-03-10", "CITY POWER", -10_000, "a")],
                as_of: "2026-03-20",
                outflows_only: true,
                expect: vec![row("city power", "a", Cadence::Monthly, 10_000, 120_000, 3, 0.95, 0.87, false)],
            },
            Case {
                name: "silence past the cadence is lapsed, and still reported",
                rows: vec![t("2026-01-10", "OLDSUB", -999, "a"), t("2026-02-10", "OLDSUB", -999, "a")],
                as_of: "2026-05-01",
                outflows_only: true,
                expect: vec![row("oldsub", "a", Cadence::Monthly, 999, 11_988, 2, 0.97, 1.0, true)],
            },
            Case {
                name: "TWO occurrences is enough, which is what makes an annual renewal findable",
                rows: vec![t("2025-03-01", "DOMAIN RENEW", -2_400, "a"), t("2026-03-01", "DOMAIN RENEW", -2_400, "a")],
                as_of: "2026-03-20",
                outflows_only: true,
                expect: vec![row("domain renew", "a", Cadence::Annual, 2_400, 2_400, 2, 1.0, 1.0, false)],
            },
            Case {
                name: "biweekly",
                rows: vec![t("2026-01-02", "LAUNDRY", -3_000, "a"), t("2026-01-16", "LAUNDRY", -3_000, "a"), t("2026-01-30", "LAUNDRY", -3_000, "a")],
                as_of: "2026-02-05",
                outflows_only: true,
                expect: vec![row("laundry", "a", Cadence::Biweekly, 3_000, 78_000, 3, 1.0, 1.0, false)],
            },
            Case {
                name: "weekly",
                rows: vec![t("2026-01-01", "BUS", -250, "a"), t("2026-01-08", "BUS", -250, "a"), t("2026-01-15", "BUS", -250, "a")],
                as_of: "2026-01-20",
                outflows_only: true,
                expect: vec![row("bus", "a", Cadence::Weekly, 250, 13_000, 3, 1.0, 1.0, false)],
            },
            Case {
                name: "quarterly",
                rows: vec![t("2025-09-01", "INSURANCE", -45_000, "a"), t("2025-12-01", "INSURANCE", -45_000, "a"), t("2026-03-02", "INSURANCE", -45_000, "a")],
                as_of: "2026-03-20",
                outflows_only: true,
                expect: vec![row("insurance", "a", Cadence::Quarterly, 45_000, 180_000, 3, 1.0, 1.0, false)],
            },
            Case {
                name: "one subscription on two cards is TWO standing charges, in first-seen order",
                rows: vec![t("2026-01-05", "SPOTIFY", -1_199, "a"), t("2026-02-05", "SPOTIFY", -1_199, "a"), t("2026-01-07", "SPOTIFY", -1_199, "b"), t("2026-02-07", "SPOTIFY", -1_199, "b")],
                as_of: "2026-02-20",
                outflows_only: true,
                expect: vec![
                    row("spotify", "a", Cadence::Monthly, 1_199, 14_388, 2, 0.97, 1.0, false),
                    row("spotify", "b", Cadence::Monthly, 1_199, 14_388, 2, 0.97, 1.0, false),
                ],
            },
            Case {
                name: "inbound money is not a standing charge",
                rows: vec![t("2026-01-15", "ACME PAYROLL", 250_000, "a"), t("2026-02-13", "ACME PAYROLL", 250_000, "a")],
                as_of: "2026-02-20",
                outflows_only: true,
                expect: vec![],
            },
            Case {
                name: "unless you ask for it",
                rows: vec![t("2026-01-15", "ACME PAYROLL", 250_000, "a"), t("2026-02-13", "ACME PAYROLL", 250_000, "a")],
                as_of: "2026-02-20",
                outflows_only: false,
                expect: vec![row("acme payroll", "a", Cadence::Monthly, 250_000, 3_000_000, 2, 0.97, 1.0, false)],
            },
            Case {
                name: "one occurrence is not a rhythm",
                rows: vec![t("2026-01-15", "ONEOFF", -500, "a")],
                as_of: "2026-02-20",
                outflows_only: true,
                expect: vec![],
            },
            Case {
                name: "an even count of amounts rounds the midpoint, and the spread is against THAT",
                rows: vec![t("2026-01-01", "CLOUD HOST", -1_000, "a"), t("2026-01-31", "CLOUD HOST", -2_000, "a"), t("2026-03-02", "CLOUD HOST", -3_000, "a"), t("2026-04-01", "CLOUD HOST", -5_000, "a")],
                as_of: "2026-04-10",
                outflows_only: true,
                expect: vec![row("cloud host", "a", Cadence::Monthly, 2_500, 30_000, 4, 1.0, 0.5, false)],
            },
        ]
    }

    #[test]
    fn every_case_matches_the_typescript_that_produced_it() {
        for c in cases() {
            let opts = DetectOptions { min_occurrences: 2, outflows_only: c.outflows_only, as_of: c.as_of };
            let got = detect_recurring(&c.rows, &opts);
            assert_eq!(got.len(), c.expect.len(), "{}: wrong number of findings — got {got:?}", c.name);
            for (g, e) in got.iter().zip(c.expect.iter()) {
                assert_eq!(g.key, e.key, "{}: key", c.name);
                assert_eq!(g.account, e.account, "{}: account", c.name);
                assert_eq!(g.cadence, e.cadence, "{}: cadence", c.name);
                assert_eq!(g.typical.minor, e.typical, "{}: typical", c.name);
                assert_eq!(g.annualised.minor, e.annualised, "{}: annualised", c.name);
                assert_eq!(g.occurrences, e.occurrences, "{}: occurrences", c.name);
                assert_eq!(g.regularity, e.regularity, "{}: regularity", c.name);
                assert_eq!(g.amount_stability, e.stability, "{}: amountStability", c.name);
                assert_eq!(g.lapsed, e.lapsed, "{}: lapsed", c.name);
            }
        }
    }

    #[test]
    fn the_parity_table_is_not_quietly_empty() {
        // A table that stopped being built would make the test above pass over nothing.
        assert!(cases().len() >= 13, "the parity table lost cases");
        assert!(cases().iter().any(|c| !c.expect.is_empty()), "every case expects nothing — the table is inert");
    }

    #[test]
    fn a_single_character_merchant_never_forms_a_group() {
        // merchantKey("X") is "", measured against the TypeScript. A group keyed on an empty string
        // would collapse every such row together, which is worse than dropping them.
        let rows = vec![t("2026-01-01", "X", -1_000, "a"), t("2026-01-31", "X", -1_000, "a")];
        assert!(detect_recurring(&rows, &DetectOptions::new("2026-02-05")).is_empty());
    }

    #[test]
    fn the_annual_total_counts_the_live_ones_only() {
        let rows = vec![
            t("2026-01-12", "NETFLIX.COM", -1_599, "a"),
            t("2026-02-12", "NETFLIX.COM", -1_599, "a"),
            t("2026-03-12", "NETFLIX.COM", -1_599, "a"),
            t("2025-01-10", "OLDSUB", -999, "a"),
            t("2025-02-10", "OLDSUB", -999, "a"),
        ];
        let rs = detect_recurring(&rows, &DetectOptions::new("2026-03-20"));
        assert_eq!(rs.len(), 2, "both are found");
        assert!(rs.iter().any(|r| r.lapsed), "the 2025 one has lapsed");
        // 1599 * 12 = 19188. The lapsed one contributes NOTHING.
        assert_eq!(total_annualised(&rs, Currency::USD).unwrap().minor, 19_188);
    }

    #[test]
    fn the_order_is_by_annual_cost_because_that_is_the_order_to_act_in() {
        let rows = vec![
            t("2026-01-12", "NETFLIX.COM", -1_599, "a"),
            t("2026-02-12", "NETFLIX.COM", -1_599, "a"),
            t("2026-01-05", "RENT LANDLORD LLC", -120_000, "a"),
            t("2026-02-05", "RENT LANDLORD LLC", -120_000, "a"),
        ];
        let rs = detect_recurring(&rows, &DetectOptions::new("2026-02-20"));
        assert_eq!(rs.iter().map(|r| r.key.as_str()).collect::<Vec<_>>(), vec!["rent landlord", "netflix"]);
        // And the key keeps BOTH words. The TypeScript joins account and key with a NUL byte for
        // exactly this reason; a space would have truncated it to "rent".
        assert_eq!(rs[0].key, "rent landlord");
    }

    #[test]
    fn a_rhythm_matching_no_cadence_is_dropped_rather_than_forced_into_one() {
        // Measured against the TypeScript. 20/21 medians to 21, which is 7 off biweekly and 9 off
        // monthly — outside both tolerances, so there is no cadence to claim.
        let rows = vec![t("2026-01-01", "CORNER STORE", -1_000, "a"), t("2026-01-21", "CORNER STORE", -1_000, "a"), t("2026-02-11", "CORNER STORE", -1_000, "a")];
        assert!(detect_recurring(&rows, &DetectOptions::new("2026-02-20")).is_empty());
        assert_eq!(classify(&[20, 21]).0, Cadence::Irregular);
        assert_eq!(classify(&[2, 3]).0, Cadence::Irregular, "3 days is 4 off weekly");
        assert_eq!(classify(&[60, 60]).0, Cadence::Irregular, "60 days falls between monthly and quarterly");
        assert_eq!(classify(&[]).0, Cadence::Irregular);
    }

    #[test]
    fn a_near_miss_is_classified_and_then_scored_down_rather_than_hidden() {
        // 2 days then 47 medians to 25, inside monthly's tolerance of 5 — so it IS called monthly.
        // What says it is not a subscription is the REGULARITY of 0.25, which is the design: the
        // cadence is a bucket, the score is the evidence. Both numbers reach the reader.
        let (cadence, regularity) = classify(&[2, 47]);
        assert_eq!(cadence, Cadence::Monthly);
        assert_eq!(round2(regularity), 0.25, "measured by running finance-recurring.ts");
    }

    #[test]
    fn irregular_has_no_annual_multiplier_and_says_so() {
        assert_eq!(Cadence::Irregular.per_year(), None);
        assert_eq!(Cadence::Monthly.per_year(), Some(12));
    }

    #[test]
    fn the_median_rounds_an_even_midpoint_half_up() {
        assert_eq!(median(&[1_000, 2_000, 3_000, 5_000]), 2_500);
        assert_eq!(median(&[1, 2]), 2, "1.5 rounds to 2, matching Math.round");
        assert_eq!(median(&[1, 2, 3]), 2);
        assert_eq!(median(&[]), 0);
        // half-up is toward POSITIVE infinity, so -1.5 is -1. No caller can reach this today —
        // amounts are absolute and gaps are non-negative — and it is pinned so that stays a choice.
        assert_eq!(median(&[-2, -1]), -1);
    }
}
